set-variable.value:
#[%dw 2.0
output application/java

var account = vars.db[0] default {}

---
"<!DOCTYPE html>
<html>
<head>
<meta charset='UTF-8'>
<title>Deposit Successful</title>

<style>
body{
margin:0;
padding:0;
background:#f4f7fb;
font-family:Arial,Helvetica,sans-serif;
}

.container{
max-width:650px;
margin:40px auto;
background:#fff;
border-radius:12px;
overflow:hidden;
box-shadow:0 8px 25px rgba(0,0,0,.12);
}

.header{
background:linear-gradient(90deg,#0047AB,#0066ff);
color:#fff;
padding:30px;
text-align:center;
}

.logo{
font-size:30px;
font-weight:bold;
}

.success{
padding:35px;
text-align:center;
}

.success-icon{
width:90px;
height:90px;
line-height:90px;
background:#16a34a;
border-radius:50%;
margin:auto;
font-size:42px;
color:#fff;
}

.success h2{
color:#16a34a;
}

.card{
margin:25px;
border:1px solid #ddd;
border-radius:10px;
overflow:hidden;
}

.card-header{
background:#0047AB;
color:#fff;
padding:15px;
font-size:18px;
font-weight:bold;
}

table{
width:100%;
border-collapse:collapse;
}

td{
padding:14px;
border-bottom:1px solid #eee;
}

.label{
font-weight:bold;
color:#555;
width:45%;
}

.value{
text-align:right;
}

.amount{
color:#16a34a;
font-size:22px;
font-weight:bold;
}

.footer{
padding:25px;
text-align:center;
background:#f8fafc;
font-size:13px;
color:#666;
}
</style>

</head>

<body>

<div class='container'>

<div class='header'>

<div class='logo'>
🏦 " ++ ((vars.inputpayload.BANKNAME[0] default "N/A") as String) ++ "
</div>

Deposit Notification

</div>

<div class='success'>

<div class='success-icon'>✓</div>

<h2>Deposit Successful</h2>

<p>Your amount has been credited successfully.</p>

</div>

<div class='card'>

<div class='card-header'>
Transaction Summary
</div>

<table>

<tr>
<td class='label'>Customer Name</td>
<td class='value'>" ++ ((vars.inputpayload.FULLNAME[0] default "N/A") as String) ++ "</td>
</tr>

<tr>
<td class='label'>Account Number</td>
<td class='value'>" ++ ((account.ACCOUNTNUMBER default vars.accountNumber) as String) ++ "</td>
</tr>

<tr>
<td class='label'>Transaction ID</td>
<td class='value'>" ++ ((vars.transactionId default "N/A") as String) ++ "</td>
</tr>

<tr>
<td class='label'>Transaction Type</td>
<td class='value'>Deposit</td>
</tr>

<tr>
<td class='label'>Amount</td>
<td class='value amount'>₹" ++ ((vars.amount default 0) as String) ++ "</td>
</tr>

<tr>
<td class='label'>Available Balance</td>
<td class='value'>₹" ++ ((vars.Balance default 0) as String) ++ "</td>
</tr>

<tr>
<td class='label'>Date & Time</td>
<td class='value'>" ++ ((now()) as String {format:'dd-MMM-yyyy hh:mm a'}) ++ "</td>
</tr>

<tr>
<td class='label'>Status</td>
<td class='value' style='color:green;font-weight:bold;'>SUCCESS</td>
</tr>

</table>

</div>

<div class='footer'>

<b>Real Bank</b><br/>

Customer Care : +91 9494207062<br/>

support@realbank.com<br/><br/>

© 2026 Real Bank

</div>

</div>

</body>

</html>"]
